CREATE OR REPLACE FUNCTION public.colab_restrita() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM colab_acessos WHERE user_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.colab_rep() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT cp.representative_party_id FROM colab_acessos ca JOIN profiles pf ON pf.id=ca.user_id AND pf.is_active JOIN consultant_profiles cp ON cp.party_id=ca.party_id WHERE ca.user_id=auth.uid() AND ca.ativo $$;
CREATE OR REPLACE FUNCTION public.colab_party_ok(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM consultant_profiles cp WHERE cp.party_id=_id AND cp.representative_party_id=public.colab_rep()) $$;
CREATE OR REPLACE FUNCTION public.colab_legacy_rep_ok(_codigo integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM legado_representantes WHERE codigo=_codigo AND party_id=public.colab_rep()) $$;
CREATE OR REPLACE FUNCTION public.colab_legacy_rem_ok(_numero integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM legado_remessas WHERE numero=_numero AND public.colab_legacy_rep_ok(representante)) $$;
CREATE OR REPLACE FUNCTION public.colab_legacy_cli_ok(_cod integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM legado_maletas m WHERE m.codcli=_cod AND public.colab_legacy_rem_ok(m.remessa)) $$;
CREATE OR REPLACE FUNCTION public.colab_praca_ok(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM legado_pracas lp JOIN legado_representantes lr ON lp.codigo=ANY(lr.pracas) WHERE lp.praca_id=_id AND lr.party_id=public.colab_rep()) $$;
CREATE OR REPLACE FUNCTION public.colab_rem_ok(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM remessas WHERE id=_id AND representante_party_id=public.colab_rep()) $$;
CREATE OR REPLACE FUNCTION public.colab_cycle_ok(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM kit_cycles c WHERE c.id=_id AND (c.representante_party_id=public.colab_rep() OR EXISTS(SELECT 1 FROM remessas r WHERE r.id=c.remessa_id AND r.representante_party_id=public.colab_rep()))) $$;
CREATE OR REPLACE FUNCTION public.colab_meu_escopo() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('colaboradora',public.colab_restrita(),'representante',public.colab_rep(),'nome',(SELECT display_name FROM parties WHERE id=public.colab_rep())) $$;
DO $ddl$ DECLARE sig text; BEGIN FOREACH sig IN ARRAY ARRAY['colab_restrita()','colab_rep()','colab_party_ok(uuid)','colab_legacy_rep_ok(integer)','colab_legacy_rem_ok(integer)','colab_legacy_cli_ok(integer)','colab_praca_ok(uuid)','colab_rem_ok(uuid)','colab_cycle_ok(uuid)','colab_meu_escopo()'] LOOP EXECUTE 'REVOKE ALL ON FUNCTION public.'||sig||' FROM PUBLIC,anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||sig||' TO authenticated,service_role'; END LOOP; END $ddl$;
DO $ddl$ DECLARE t text; p text; BEGIN FOR t,p IN SELECT * FROM (VALUES ('legado_remessas','public.colab_legacy_rep_ok(representante)'),('legado_maletas','public.colab_legacy_rem_ok(remessa)'),('legado_consultoras','public.colab_legacy_cli_ok(codcli)'),('legado_representantes','public.colab_legacy_rep_ok(codigo)'),('legado_pracas','NOT public.colab_restrita() OR EXISTS(SELECT 1 FROM legado_representantes lr WHERE lr.party_id=public.colab_rep() AND codigo=ANY(lr.pracas))'),('legado_maleta_categorias','public.colab_legacy_rem_ok(remessa)'),('legado_maleta_vendidos','public.colab_legacy_rem_ok(remessa)'),('legado_notas','public.colab_legacy_rem_ok(remessa)'),('legado_acertos_consultora','public.colab_legacy_rem_ok(remessa)'),('legado_acertos_praca','public.colab_legacy_rep_ok(representante)'),('legado_maleta_status','public.colab_legacy_rem_ok(remessa)'),('parties','public.colab_party_ok(id)'),('consultant_profiles','public.colab_party_ok(party_id)'),('party_roles','public.colab_party_ok(party_id)'),('contact_points','public.colab_party_ok(party_id)'),('party_addresses','public.colab_party_ok(party_id)'),('party_links','NOT public.colab_restrita()'),('remessas','public.colab_rem_ok(id)'),('cob_pracas','public.colab_praca_ok(id)'),('kit_cycles','public.colab_cycle_ok(id)')) s(tab,pred) LOOP EXECUTE format('CREATE OR REPLACE VIEW public.colab_v_%I AS SELECT * FROM public.%I WHERE (%s)',t,t,p); EXECUTE format('REVOKE ALL ON public.colab_v_%I FROM PUBLIC,anon,authenticated',t); EXECUTE format('GRANT SELECT ON public.colab_v_%I TO service_role',t); END LOOP; END $ddl$;